#include "lexer.h"
#include <iostream>
#include <fstream>
#include <sstream>
int main(int argc, char** argv) {
    std::ifstream f(argc > 1 ? argv[1] : "");
    std::ostringstream ss; ss << f.rdbuf();
    Lexer lex(ss.str());
    auto toks = lex.tokenize();
    for (auto& t : toks)
        std::cout << (int)t.kind << "\t'" << t.value << "'\t" << t.line << ":" << t.col << "\n";
}
EOF
